describe('Modal Dialog Focus Return Functionality', () => {
  beforeEach(() => {
    cy.visit('/modal-dialog');
  });

  it('should return focus to trigger button after modal closes', () => {
    // Intercept modal close API
    cy.intercept('POST', '/api/modal/close').as('modalClose');

    // Open modal
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal-dialog"]').should('be.visible');

    // Verify modal is open
    cy.get('[data-testid="modal-title"]').should('contain', 'Modal Title');
    cy.get('[data-testid="modal-content"]').should('be.visible');

    // Verify focus is on modal content
    cy.get('[data-testid="modal-content"]').should('have.focus');

    // Close modal
    cy.get('[data-testid="modal-close-btn"]').click();

    // Wait for modal close API
    cy.wait('@modalClose');

    // Verify modal is closed
    cy.get('[data-testid="modal-dialog"]').should('not.exist');

    // Verify focus is back on trigger button
    cy.get('[data-testid="open-modal-btn"]').should('have.focus');
  });

  it('should handle focus return when modal is closed programmatically', () => {
    // Open modal
    cy.get('[data-testid="open-modal-btn"]').click();
    cy.get('[data-testid="modal-dialog"]').should('be.visible');

    // Verify modal is open
    cy.get('[data-testid="modal-title"]').should('contain', 'Modal Title');
    cy.get('[data-testid="modal-content"]').should('be.visible');

    // Verify focus is on modal content
    cy.get('[data-testid="modal-content"]').should('have.focus');

    // Close modal programmatically
    cy.get('[data-testid="modal-dialog"]').then((modal) => {
      modal.find('[data-testid="modal-close-btn"]').click();
    });

    // Wait for modal close API
    cy.wait('@modalClose');

    // Verify modal is closed
    cy.get('[data-testid="modal-dialog"]').should('not.exist');

    // Verify focus is back on trigger button
    cy.get('[data-testid="open-modal-btn"]').should('have.focus');
  });
});
